describe('Bottom Sheet Replacement for Dropdowns on Mobile', () => {
  beforeEach(() => {
    cy.visit('/mobile-form');
  });

  it('should display bottom sheet when dropdown is clicked on mobile view', () => {
    // Verify mobile view is active
    cy.viewport('iphone-x');
    cy.get('[data-testid="mobile-form-container"]').should('be.visible');

    // Verify dropdown is visible
    cy.get('[data-testid="country-dropdown"]').should('be.visible');

    // Click dropdown to trigger bottom sheet
    cy.get('[data-testid="country-dropdown"]').click();

    // Verify bottom sheet appears
    cy.get('[data-testid="bottom-sheet"]').should('be.visible');
    cy.get('[data-testid="bottom-sheet-header"]').should('contain', 'Select Country');

    // Verify options are listed in bottom sheet
    cy.get('[data-testid="bottom-sheet-option"]').first().should('contain', 'United States');
    cy.get('[data-testid="bottom-sheet-option"]').last().should('contain', 'Australia');

    // Verify close button is visible
    cy.get('[data-testid="bottom-sheet-close-button"]').should('be.visible');

    // Verify selection is possible
    cy.get('[data-testid="bottom-sheet-option"]').eq(1).click();
    cy.get('[data-testid="bottom-sheet"]').should('not.exist');

    // Verify selected value is displayed
    cy.get('[data-testid="country-display"]').should('contain', 'Canada');
  });

  it('should handle bottom sheet dismissal via backdrop click and empty state', () => {
    // Verify mobile view is active
    cy.viewport('iphone-12');
    cy.get('[data-testid="mobile-form-container"]').should('be.visible');

    // Click dropdown to open bottom sheet
    cy.get('[data-testid="state-dropdown"]').click();

    // Verify bottom sheet appears
    cy.get('[data-testid="bottom-sheet"]').should('be.visible');

    // Click backdrop to dismiss
    cy.get('[data-testid="bottom-sheet-backdrop"]').click();

    // Verify bottom sheet is dismissed
    cy.get('[data-testid="bottom-sheet"]').should('not.exist');

    // Verify dropdown reverts to default state
    cy.get('[data-testid="state-display"]').should('contain', 'Select State');

    // Verify empty state message is shown when no options exist
    cy.get('[data-testid="empty-state-message"]').should('be.visible');
    cy.get('[data-testid="empty-state-message"]').should('contain', 'No states available');

    // Verify empty state message is hidden when options are loaded
    cy.get('[data-testid="state-dropdown"]').click();
    cy.get('[data-testid="empty-state-message"]').should('not.exist');
    cy.get('[data-testid="bottom-sheet-option"]').first().should('be.visible');
  });
});
